ALTER TABLE public.mt_rotina_riscos ADD COLUMN impacto text NOT NULL DEFAULT '', ADD COLUMN atribuido_cadeira_id uuid REFERENCES public.mt_cadeiras(id), ADD COLUMN prazo_desejado date, ADD COLUMN publicado_ciclo date, ADD COLUMN publicado_em timestamptz, ADD COLUMN sinalizado_por_nome text, ADD COLUMN plano_acao text NOT NULL DEFAULT '', ADD COLUMN prazo_plano date, ADD COLUMN resposta_status text NOT NULL DEFAULT 'aberto' CHECK (resposta_status IN ('aberto','em_andamento','resolvido','nao_procede')), ADD COLUMN justificativa_resposta text NOT NULL DEFAULT '', ADD COLUMN respondido_em timestamptz, ADD COLUMN respondido_por uuid, ADD COLUMN motivo_reabertura text;
CREATE TABLE public.mt_impedimento_respostas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), risco_id uuid NOT NULL REFERENCES public.mt_rotina_riscos(id), ciclo date NOT NULL, plano text NOT NULL, prazo date NOT NULL, status text NOT NULL CHECK(status IN ('aberto','em_andamento','resolvido','nao_procede')), justificativa text NOT NULL DEFAULT '', respondido_por uuid NOT NULL, respondido_em timestamptz NOT NULL DEFAULT now(), UNIQUE(risco_id,ciclo));
GRANT SELECT ON public.mt_impedimento_respostas TO authenticated; GRANT ALL ON public.mt_impedimento_respostas TO service_role; ALTER TABLE public.mt_impedimento_respostas ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.mt_impedimento_auditoria (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), risco_id uuid NOT NULL REFERENCES public.mt_rotina_riscos(id), acao text NOT NULL, anterior jsonb, novo jsonb, usuario_id uuid, usuario_nome text, criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.mt_impedimento_auditoria TO authenticated; GRANT ALL ON public.mt_impedimento_auditoria TO service_role; ALTER TABLE public.mt_impedimento_auditoria ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.rotina_atividade_permitida(_origem uuid, _destino uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.acesso_modulo(auth.uid(),'rotina',false) AND (public.mt_is_governanca(auth.uid()) OR public.proj_eh_ceo(auth.uid()) OR _origem=public.mt_cadeira_do_usuario(auth.uid()) OR _destino=public.mt_cadeira_do_usuario(auth.uid())) $$;
REVOKE ALL ON FUNCTION public.rotina_atividade_permitida(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rotina_atividade_permitida(uuid,uuid) TO authenticated;
CREATE POLICY envolvidos ON public.mt_impedimento_respostas FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.mt_rotina_riscos r WHERE r.id=risco_id AND public.rotina_atividade_permitida(r.cadeira_id,r.atribuido_cadeira_id)));
CREATE POLICY envolvidos ON public.mt_impedimento_auditoria FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.mt_rotina_riscos r WHERE r.id=risco_id AND public.rotina_atividade_permitida(r.cadeira_id,r.atribuido_cadeira_id)));
CREATE POLICY riscos_privacidade ON public.mt_rotina_riscos AS RESTRICTIVE FOR SELECT TO authenticated USING (public.rotina_atividade_permitida(cadeira_id,CASE WHEN publicado_em IS NOT NULL THEN atribuido_cadeira_id END));
CREATE OR REPLACE FUNCTION public.mt_rotina_riscos_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_OP='INSERT' THEN
  IF btrim(NEW.descricao)='' THEN RAISE EXCEPTION 'Informe a descrição'; END IF;
  IF NEW.atribuido_cadeira_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.mt_cadeiras WHERE id=NEW.atribuido_cadeira_id AND ativo) THEN RAISE EXCEPTION 'Cadeira destinatária inativa'; END IF;
  NEW.criado_por:=auth.uid(); NEW.publicado_ciclo:=NULL; NEW.publicado_em:=NULL; NEW.plano_acao:=''; NEW.prazo_plano:=NULL; NEW.resposta_status:='aberto'; NEW.justificativa_resposta:=''; NEW.respondido_em:=NULL; NEW.respondido_por:=NULL; NEW.sinalizado_por_nome:=NULL;
 ELSE
  IF NEW.descricao IS DISTINCT FROM OLD.descricao OR NEW.tipo IS DISTINCT FROM OLD.tipo OR NEW.cadeira_id IS DISTINCT FROM OLD.cadeira_id OR NEW.semana_criada IS DISTINCT FROM OLD.semana_criada OR NEW.criado_por IS DISTINCT FROM OLD.criado_por THEN RAISE EXCEPTION 'A descrição do risco não pode ser alterada depois de registrada'; END IF;
  IF current_setting('app.impedimento_operacao',true) IS DISTINCT FROM NEW.id::text AND (NEW.atribuido_cadeira_id IS DISTINCT FROM OLD.atribuido_cadeira_id OR NEW.impacto IS DISTINCT FROM OLD.impacto OR NEW.prazo_desejado IS DISTINCT FROM OLD.prazo_desejado OR NEW.publicado_em IS DISTINCT FROM OLD.publicado_em OR NEW.publicado_ciclo IS DISTINCT FROM OLD.publicado_ciclo OR NEW.sinalizado_por_nome IS DISTINCT FROM OLD.sinalizado_por_nome OR NEW.plano_acao IS DISTINCT FROM OLD.plano_acao OR NEW.prazo_plano IS DISTINCT FROM OLD.prazo_plano OR NEW.resposta_status IS DISTINCT FROM OLD.resposta_status OR NEW.justificativa_resposta IS DISTINCT FROM OLD.justificativa_resposta OR NEW.respondido_em IS DISTINCT FROM OLD.respondido_em OR NEW.respondido_por IS DISTINCT FROM OLD.respondido_por OR NEW.motivo_reabertura IS DISTINCT FROM OLD.motivo_reabertura OR (OLD.atribuido_cadeira_id IS NOT NULL AND (NEW.resolvido_em IS DISTINCT FROM OLD.resolvido_em OR NEW.reaberto_em IS DISTINCT FROM OLD.reaberto_em))) THEN RAISE EXCEPTION 'Use a resposta ou reabertura auditada do impedimento'; END IF;
 END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER mt_risco_insercao_guard BEFORE INSERT ON public.mt_rotina_riscos FOR EACH ROW EXECUTE FUNCTION public.mt_rotina_riscos_guard();
CREATE OR REPLACE FUNCTION public.rotina_impedimento_auditar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.mt_impedimento_auditoria(risco_id,acao,anterior,novo,usuario_id,usuario_nome) VALUES(NEW.id,CASE WHEN TG_OP='INSERT' THEN 'atribuição' WHEN NEW.reaberto_em IS DISTINCT FROM OLD.reaberto_em THEN 'reabertura' WHEN NEW.publicado_em IS DISTINCT FROM OLD.publicado_em THEN 'envio' ELSE 'resposta/status' END,CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) END,to_jsonb(NEW),auth.uid(),(SELECT display_name FROM public.profiles WHERE user_id=auth.uid())); RETURN NEW; END $$;
CREATE TRIGGER mt_impedimento_auditar AFTER INSERT OR UPDATE ON public.mt_rotina_riscos FOR EACH ROW EXECUTE FUNCTION public.rotina_impedimento_auditar();
ALTER TABLE public.rotina_avisos_envios DROP CONSTRAINT rotina_avisos_envios_tipo_check;
ALTER TABLE public.rotina_avisos_envios ADD CONSTRAINT rotina_avisos_envios_tipo_check CHECK(tipo IN ('abertura','lembrete','manual','impedimento'));
ALTER TABLE public.rotina_avisos_envios ADD COLUMN impedimento_id uuid REFERENCES public.mt_rotina_riscos(id);
DROP INDEX public.rotina_avisos_automaticos_unicos;
CREATE UNIQUE INDEX rotina_avisos_automaticos_unicos ON public.rotina_avisos_envios(cadeira_id,usuario_id,ciclo,canal,tipo) WHERE tipo IN ('abertura','lembrete');
CREATE UNIQUE INDEX rotina_impedimento_envio_unico ON public.rotina_avisos_envios(impedimento_id,usuario_id,canal) WHERE tipo='impedimento';
CREATE OR REPLACE FUNCTION public.rotina_impedimento_responder(_id uuid,_ciclo date,_plano text,_prazo date,_status text,_justificativa text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.mt_rotina_riscos%ROWTYPE; v_context text; BEGIN
 SELECT * INTO r FROM public.mt_rotina_riscos WHERE id=_id FOR UPDATE;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.acesso_modulo(auth.uid(),'rotina',true) OR NOT coalesce((public.mt_is_governanca(auth.uid()) OR public.proj_eh_ceo(auth.uid()) OR r.atribuido_cadeira_id=public.mt_cadeira_do_usuario(auth.uid())),false) THEN RAISE EXCEPTION 'Sem permissão para responder'; END IF;
 IF r.publicado_ciclo IS NULL OR _ciclo IS NULL OR _ciclo<=r.publicado_ciclo OR extract(isodow FROM _ciclo)<>1 THEN RAISE EXCEPTION 'Responda a partir do ciclo seguinte ao envio'; END IF;
 IF btrim(coalesce(_plano,''))='' OR _prazo IS NULL THEN RAISE EXCEPTION 'Plano de ação e prazo são obrigatórios'; END IF;
 IF _status IS NULL OR _status NOT IN ('aberto','em_andamento','resolvido','nao_procede') THEN RAISE EXCEPTION 'Status inválido'; END IF;
 IF _status='nao_procede' AND btrim(coalesce(_justificativa,''))='' THEN RAISE EXCEPTION 'Não procede exige justificativa'; END IF;
 IF r.respondido_em IS NOT NULL AND _ciclo < (SELECT max(ciclo) FROM public.mt_impedimento_respostas WHERE risco_id=_id) THEN RAISE EXCEPTION 'Não altere uma resposta histórica'; END IF;
 INSERT INTO public.mt_impedimento_respostas(risco_id,ciclo,plano,prazo,status,justificativa,respondido_por) VALUES(_id,_ciclo,btrim(_plano),_prazo,_status,coalesce(_justificativa,''),auth.uid()) ON CONFLICT(risco_id,ciclo) DO UPDATE SET plano=EXCLUDED.plano,prazo=EXCLUDED.prazo,status=EXCLUDED.status,justificativa=EXCLUDED.justificativa,respondido_por=auth.uid(),respondido_em=now();
 v_context:=current_setting('app.impedimento_operacao',true); PERFORM set_config('app.impedimento_operacao',_id::text,true);
 UPDATE public.mt_rotina_riscos SET plano_acao=btrim(_plano),prazo_plano=_prazo,resposta_status=_status,justificativa_resposta=coalesce(_justificativa,''),respondido_por=auth.uid(),respondido_em=now(),resolvido_em=CASE WHEN _status IN ('resolvido','nao_procede') THEN now() END,resolvido_por=CASE WHEN _status IN ('resolvido','nao_procede') THEN auth.uid() END WHERE id=_id;
 PERFORM set_config('app.impedimento_operacao',coalesce(v_context,''),true); END $$;
REVOKE ALL ON FUNCTION public.rotina_impedimento_responder(uuid,date,text,date,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rotina_impedimento_responder(uuid,date,text,date,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.rotina_impedimento_reabrir(_id uuid,_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.mt_rotina_riscos%ROWTYPE; v_context text; BEGIN
 SELECT * INTO r FROM public.mt_rotina_riscos WHERE id=_id FOR UPDATE;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.acesso_modulo(auth.uid(),'rotina',true) OR NOT coalesce((public.mt_is_governanca(auth.uid()) OR public.proj_eh_ceo(auth.uid()) OR r.cadeira_id=public.mt_cadeira_do_usuario(auth.uid())),false) THEN RAISE EXCEPTION 'Somente quem sinalizou ou Governança/CEO pode reabrir'; END IF;
 IF btrim(coalesce(_motivo,''))='' THEN RAISE EXCEPTION 'Informe o motivo da reabertura'; END IF;
 IF r.publicado_em IS NULL THEN RAISE EXCEPTION 'Impedimento ainda não enviado'; END IF;
 v_context:=current_setting('app.impedimento_operacao',true); PERFORM set_config('app.impedimento_operacao',_id::text,true);
 UPDATE public.mt_rotina_riscos SET resposta_status='aberto',motivo_reabertura=btrim(_motivo),reaberto_em=now(),resolvido_em=NULL,resolvido_por=NULL WHERE id=_id;
 PERFORM set_config('app.impedimento_operacao',coalesce(v_context,''),true); END $$;
REVOKE ALL ON FUNCTION public.rotina_impedimento_reabrir(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rotina_impedimento_reabrir(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.rotina_impedimentos_ciclo(_cadeira uuid,_ciclo date) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('origem_nome',o.nome,'destino_nome',d.nome,'resposta_ciclo',(SELECT to_jsonb(x) FROM public.mt_impedimento_respostas x WHERE x.risco_id=r.id AND x.ciclo=_ciclo AND (r.reaberto_em IS NULL OR x.respondido_em>r.reaberto_em)))), '[]'::jsonb) FROM public.mt_rotina_riscos r JOIN public.mt_cadeiras o ON o.id=r.cadeira_id LEFT JOIN public.mt_cadeiras d ON d.id=r.atribuido_cadeira_id WHERE public.rotina_atividade_permitida(r.cadeira_id,CASE WHEN r.publicado_em IS NOT NULL THEN r.atribuido_cadeira_id END) AND coalesce((public.mt_is_governanca(auth.uid()) OR public.proj_eh_ceo(auth.uid()) OR _cadeira=public.mt_cadeira_do_usuario(auth.uid())),false) AND r.atribuido_cadeira_id IS NOT NULL AND r.semana_criada<=_ciclo AND (r.cadeira_id=_cadeira OR (r.atribuido_cadeira_id=_cadeira AND r.publicado_ciclo<_ciclo)) $$;
REVOKE ALL ON FUNCTION public.rotina_impedimentos_ciclo(uuid,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rotina_impedimentos_ciclo(uuid,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.rotina_impedimentos_enviar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.mt_rotina_riscos%ROWTYPE; d record; v_context text; BEGIN
 IF NEW.tipo<>'checkin' OR NEW.status<>'enviado' THEN RETURN NEW; END IF;
 FOR r IN SELECT * FROM public.mt_rotina_riscos WHERE cadeira_id=NEW.cadeira_id AND semana_criada<=NEW.semana AND atribuido_cadeira_id IS NOT NULL AND publicado_em IS NULL AND resolvido_em IS NULL FOR UPDATE LOOP
 v_context:=current_setting('app.impedimento_operacao',true); PERFORM set_config('app.impedimento_operacao',r.id::text,true);
 UPDATE public.mt_rotina_riscos SET publicado_ciclo=NEW.semana,publicado_em=now(),sinalizado_por_nome=coalesce(NEW.enviado_por_nome,(SELECT diretor_nome FROM public.mt_cadeiras WHERE id=NEW.cadeira_id)) WHERE id=r.id;
 PERFORM set_config('app.impedimento_operacao',coalesce(v_context,''),true);
 SELECT c.id,c.diretor_user_id,p.email,coalesce(p.display_name,c.diretor_nome,c.nome) nome INTO d FROM public.mt_cadeiras c JOIN public.mt_usuarios u ON u.user_id=c.diretor_user_id AND u.cadeira_id=c.id JOIN public.profiles p ON p.user_id=u.user_id WHERE c.id=r.atribuido_cadeira_id AND c.ativo AND p.email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' AND public.acesso_modulo(u.user_id,'rotina',false);
 IF FOUND THEN INSERT INTO public.rotina_avisos_envios(cadeira_id,usuario_id,ciclo,tipo,destinatario,nome,pendencias,status,solicitado_por,impedimento_id) VALUES(d.id,d.diretor_user_id,NEW.semana+7,'impedimento',d.email,d.nome,jsonb_build_object('quem_sinalizou',coalesce(NEW.enviado_por_nome,''),'cadeira_origem',(SELECT nome FROM public.mt_cadeiras WHERE id=NEW.cadeira_id),'descricao',r.descricao,'prazo_desejado',r.prazo_desejado,'link','/metas/semanal?semana='||(NEW.semana+7)::text||'&impedimento='||r.id::text),'aguardando',auth.uid(),r.id) ON CONFLICT DO NOTHING; END IF;
 END LOOP; RETURN NEW; END $$;
CREATE TRIGGER rotina_impedimentos_enviar AFTER INSERT OR UPDATE ON public.mt_checkins FOR EACH ROW EXECUTE FUNCTION public.rotina_impedimentos_enviar();
CREATE OR REPLACE FUNCTION public.rotina_impedimentos_completude() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; resp public.mt_impedimento_respostas%ROWTYPE; c jsonb; total integer:=0; feitos integer:=0; v_ciclo date; BEGIN
 IF NEW.tipo<>'checkout' OR NEW.status<>'enviado' THEN RETURN NEW; END IF; v_ciclo:=NEW.semana+7;
 FOR r IN SELECT * FROM public.mt_rotina_riscos WHERE atribuido_cadeira_id=NEW.cadeira_id AND publicado_ciclo<v_ciclo AND (resposta_status NOT IN ('resolvido','nao_procede') OR EXISTS(SELECT 1 FROM public.mt_impedimento_respostas x WHERE x.risco_id=mt_rotina_riscos.id AND x.ciclo=v_ciclo)) LOOP
 total:=total+1; SELECT * INTO resp FROM public.mt_impedimento_respostas WHERE risco_id=r.id AND ciclo=v_ciclo AND (r.reaberto_em IS NULL OR respondido_em>r.reaberto_em);
 IF NOT FOUND OR btrim(resp.plano)='' OR resp.prazo IS NULL OR (resp.status='nao_procede' AND btrim(resp.justificativa)='') THEN RAISE EXCEPTION 'Responda plano, prazo e status do impedimento recebido: %',r.descricao; END IF; feitos:=feitos+1; END LOOP;
 IF TG_OP='UPDATE' AND OLD.conteudo->>'primeiro_envio_em' IS NOT NULL THEN RETURN NEW; END IF;
 c:=coalesce(NEW.conteudo->'completude','{"total":0,"feitos":0,"faltando":[]}');
 NEW.conteudo:=jsonb_set(NEW.conteudo,'{completude}',jsonb_build_object('total',coalesce((c->>'total')::int,0)+total,'feitos',coalesce((c->>'feitos')::int,0)+feitos,'faltando',coalesce(c->'faltando','[]'::jsonb))); RETURN NEW; END $$;
CREATE TRIGGER rotina_impedimentos_completude BEFORE INSERT OR UPDATE ON public.mt_checkins FOR EACH ROW EXECUTE FUNCTION public.rotina_impedimentos_completude();
CREATE OR REPLACE FUNCTION public.rotina_atividades_abertas(_ciclo date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE saida jsonb:='[]'; c record; a record; r record; p record; BEGIN
 IF auth.uid() IS NULL OR NOT public.acesso_modulo(auth.uid(),'rotina',false) THEN RETURN saida; END IF;
 FOR r IN SELECT r.*,o.nome origem_nome,d.nome destino_nome FROM public.mt_rotina_riscos r JOIN public.mt_cadeiras o ON o.id=r.cadeira_id LEFT JOIN public.mt_cadeiras d ON d.id=r.atribuido_cadeira_id WHERE r.publicado_em IS NOT NULL AND r.publicado_ciclo<=_ciclo AND public.rotina_atividade_permitida(r.cadeira_id,r.atribuido_cadeira_id) LOOP
 saida:=saida||jsonb_build_array(jsonb_build_object('id',r.id,'origem','impedimento','titulo',r.descricao,'origem_label','Impedimento sinalizado por '||coalesce(r.sinalizado_por_nome,r.origem_nome)||' / '||r.origem_nome||' (ciclo '||to_char(r.publicado_ciclo,'DD/MM')||')','responsavel',r.destino_nome,'quem_sinalizou',r.sinalizado_por_nome,'plano',r.plano_acao,'prazo',r.prazo_plano,'status',r.resposta_status,'cadeira_id',r.atribuido_cadeira_id,'sinalizador_cadeira_id',r.cadeira_id,'atrasado',coalesce(r.prazo_plano<(now() AT TIME ZONE 'America/Sao_Paulo')::date AND r.resposta_status<>'resolvido',false)));
 END LOOP;
 FOR c IN SELECT * FROM public.mt_cadeiras WHERE public.rotina_atividade_permitida(id,NULL) LOOP
 FOR a IN SELECT * FROM public.gov_acoes_da_cadeira(c.id) LOOP
 saida:=saida||jsonb_build_array(jsonb_build_object('id',a.id,'origem','ata','titulo',a.titulo,'origem_label','Ata · '||coalesce(a.reuniao_titulo,'Reunião')||' ('||coalesce(to_char(a.reuniao_data,'DD/MM/YYYY'),'sem data')||')','responsavel',c.nome,'quem_sinalizou','Governança','plano',a.descricao,'prazo',a.prazo,'status','aberto','cadeira_id',c.id,'atrasado',coalesce(a.prazo<(now() AT TIME ZONE 'America/Sao_Paulo')::date,false)));
 END LOOP;
 FOR p IN SELECT w.semana,q.value item FROM public.mt_checkins w CROSS JOIN LATERAL jsonb_array_elements(coalesce(w.conteudo->'prioridades','[]')) q WHERE w.cadeira_id=c.id AND w.tipo='checkin' AND w.status='enviado' AND w.semana<=_ciclo AND btrim(coalesce(q.value->>'titulo',''))<>'' AND NOT EXISTS(SELECT 1 FROM public.mt_checkins co CROSS JOIN LATERAL jsonb_array_elements(coalesce(co.conteudo->'entregas','[]')) e WHERE co.cadeira_id=c.id AND co.tipo='checkout' AND co.status='enviado' AND co.semana<=_ciclo AND e->>'status'='entregue' AND coalesce(e->>'herdada_de',co.semana::text)=w.semana::text AND coalesce(nullif(e->>'prioridade_id',''),e->>'titulo')=coalesce(nullif(q.value->>'id',''),q.value->>'titulo')) LOOP
 saida:=saida||jsonb_build_array(jsonb_build_object('id',coalesce(p.item->>'id',p.item->>'titulo')||p.semana::text,'origem','prioridade','titulo',p.item->>'titulo','origem_label','Prioridade estratégica apontada (ciclo '||to_char(p.semana,'DD/MM')||')','responsavel',c.nome,'quem_sinalizou',c.diretor_nome,'plano',p.item->>'resultado','prazo',p.item->>'prazo','status','aberto','cadeira_id',c.id,'atrasado',coalesce(nullif(p.item->>'prazo','')::date<(now() AT TIME ZONE 'America/Sao_Paulo')::date,false)));
 END LOOP; END LOOP; RETURN saida; END $$;
REVOKE ALL ON FUNCTION public.rotina_atividades_abertas(date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rotina_atividades_abertas(date) TO authenticated;